(function() {'use strict';
const pct=document.getElementById('pct');const fill=document.getElementById('logoFill');const loader=document.getElementById('preloader');const page=document.getElementById('page')||document.querySelector('.portfolio-section')||document.body;
let count=0;const duration=2400;
const interval=28;const steps=duration/interval;let step=0;
const ease=t=>1-Math.pow(1-t,3); function lockScroll() {document.body.style.overflow='hidden';} function unlockScroll() {document.body.style.overflow='';} function runLoader() {lockScroll();const timer=setInterval(()=>{step++;const progress=ease(step/steps);count=Math.min(100,Math.round(progress*100));if (pct) {pct.textContent=count;}
if (fill) {const fromTop=100-count;fill.style.clipPath=`inset(${fromTop}% 0 0 0)`;}if (count>=100) {clearInterval(timer);
setTimeout(()=>{if (fill) {fill.classList.add('reveal');}setTimeout(()=>{if (loader) {loader.classList.add('hide');}document.body.classList.add('ready');unlockScroll();
if (page&&page!==document.body) {page.classList.add('visible');}},500);},200);}},interval);} function init() {
if (document.readyState==='loading') {document.addEventListener('DOMContentLoaded',runLoader);}else {runLoader();}
setTimeout(()=>{if (loader&&!loader.classList.contains('hide')) {if (fill) {fill.classList.add('reveal');}loader.classList.add('hide');document.body.classList.add('ready');unlockScroll();if (page&&page!==document.body) {page.classList.add('visible');}}},5000);}
init();
window.PremiumLoader={hide:function() {if (loader) {if (fill) {fill.classList.add('reveal');}loader.classList.add('hide');document.body.classList.add('ready');unlockScroll();}},isHidden:function() {return loader?loader.classList.contains('hide'):true;}};})();